<div class="section-head"><h1>หมวดหมู่บทความ</h1><a class="outline-link" href="<?= base_url().'admin/blog' ?>">← กลับบทความ</a></div><?php if ($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<div class="blog-category-layout"><form class="panel stack-form" method="post"><?= csrf_field() ?><h2><?= !empty($editing['id']) ? 'แก้ไขหมวดหมู่' : 'เพิ่มหมวดหมู่' ?></h2><input type="hidden" name="id" value="<?= (int)($editing['id'] ?? 0) ?>"><label>ชื่อหมวดหมู่<input name="name" required maxlength="100" value="<?= e($editing['name'] ?? '') ?>" placeholder="เช่น เที่ยวญี่ปุ่น"></label><label>URL หมวดหมู่<input name="slug" maxlength="180" value="<?= e($editing['slug'] ?? '') ?>" placeholder="สร้างอัตโนมัติจากชื่อ"></label><button type="submit" class="btn">บันทึกหมวดหมู่</button><?php if ($editing): ?><a href="<?= base_url().'admin/blog/categories' ?>">ยกเลิกการแก้ไข</a><?php endif ?></form><div class="panel blog-table-wrap"><table class="blog-table"><thead><tr><th>ชื่อหมวดหมู่</th><th>URL</th><th>จัดการ</th></tr></thead><tbody><?php foreach ($categories as $c): ?><tr><td><?= e($c['name']) ?></td><td><?= e($c['slug']) ?></td><td><div class="blog-actions"><a href="?edit=<?= $c['id'] ?>">แก้ไข</a><form method="post" data-blog-confirm="ลบหมวดหมู่นี้? บทความจะยังอยู่ แต่ไม่มีหมวดหมู่"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $c['id'] ?>"><input type="hidden" name="action" value="delete"><button class="text-button" type="submit">ลบ</button></form></div></td></tr><?php endforeach ?><?php if (!$categories): ?><tr><td colspan="3">ยังไม่มีหมวดหมู่ เพิ่มหมวดหมู่แรกได้เลย</td></tr><?php endif ?></tbody></table></div></div>
